### src/services/emailInvite.ts
import nodemailer from "nodemailer";
import { mailConfig } from "../config/mail";
import type { InviteResult } from "../types/invite";

export async function sendInvite(email: string): Promise<InviteResult> {
  const transport = nodemailer.createTransport(mailConfig.smtpUrl);
  await transport.sendMail({ to: email, subject: "Invite", text: "Join us" });
  return { email, sent: true };
}


### src/services/s3Upload.ts
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { storageConfig } from "../config/storage";
import type { UploadResult } from "../types/upload";

const client = new S3Client({ region: storageConfig.region });

export async function uploadImage(file: Blob): Promise<UploadResult> {
  const key = `images/${crypto.randomUUID()}.png`;
  await client.send(new PutObjectCommand({ Bucket: storageConfig.bucket, Key: key, Body: file }));
  return { key, bucket: storageConfig.bucket };
}


### src/types/invite.ts
export interface InviteResult {
  email: string;
  sent: boolean;
}


### src/types/upload.ts
export interface UploadResult {
  key: string;
  bucket: string | undefined;
}

